      <p className="text-gray-700 mb-4">「つながるメガネ」という独自サービスにより、購入後のメガネと処方箋データが連携され、次回購入時の参考情報として活用できます。これにより、度数の進行を追跡でき、より正確な処方が可能になります。</p>
